64	/**
65	 * @author Vitaliy Fedoriv
66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /**
74	     * A pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
75	     * and a dotted domain. Deliberately conservative so obviously malformed values (e.g. a bare
76	     * word with no {@code @}) are rejected while ordinary addresses are accepted.
77	     */
78	    private static final Pattern EMAIL_PATTERN =
79	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
80	
81	    /** Dedicated audit logger; carries owner lifecycle side-effects. */
82	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
83	
84	    private final ClinicService clinicService;
85	
86	    private final OwnerMapper ownerMapper;
87	
88	    private final PetMapper petMapper;
89	
90	    private final VisitMapper visitMapper;
91	
92	    public OwnerRestControllerV1(ClinicService clinicService,
93	                                 OwnerMapper ownerMapper,
94	                                 PetMapper petMapper,
95	                                 VisitMapper visitMapper) {
96	        this.clinicService = clinicService;
97	        this.ownerMapper = ownerMapper;
98	        this.petMapper = petMapper;
99	        this.visitMapper = visitMapper;
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
105	        Collection<Owner> owners;
106	        if (lastName != null) {
107	            owners = this.clinicService.findOwnerByLastName(lastName);
108	        } else {
109	            owners = this.clinicService.findAllOwners();
110	        }
111	        if (owners.isEmpty()) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
120	        Owner owner = this.clinicService.findOwnerById(ownerId);
121	        if (owner == null) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
130	        List<String> missingFields = new ArrayList<>();
131	        if (isBlank(ownerFieldsDto.getFirstName())) {
132	            missingFields.add("firstName");
133	        }
134	        if (isBlank(ownerFieldsDto.getLastName())) {
135	            missingFields.add("lastName");
136	        }
137	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
138	        if (isBlank(normalizedAddress)) {
139	            missingFields.add("address");
140	        }
141	        if (isBlank(ownerFieldsDto.getCity())) {
142	            missingFields.add("city");
143	        }
144	        if (isBlank(ownerFieldsDto.getTelephone())) {
145	            missingFields.add("telephone");
146	        }
147	        if (!missingFields.isEmpty()) {
148	            throw new MissingOwnerFieldsException(missingFields);
149	        }
150	        LocalDate registrationDate = toBusinessDay(
151	            ownerFieldsDto.getRegistrationDate() != null
152	                ? ownerFieldsDto.getRegistrationDate()
153	                : LocalDate.now());
154	        long registeredOnDay = this.clinicService.findAllOwners().stream()
155	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
156	            .count();
157	        if (registeredOnDay >= 100) {
158	            throw new DailyRegistrationLimitException(
159	                "100 or more owners have already been registered today");
160	        }
161	        boolean bulkSignupWarning = registeredOnDay > 80;
162	        String city = ownerFieldsDto.getCity();
163	        long ownersInCity = this.clinicService.findAllOwners().stream()
164	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
165	            .count();
166	        if (ownersInCity >= 50) {
167	            throw new CityAtCapacityException(
168	                "the owner's city already contains 50 or more owners");
169	        }
170	        ownerFieldsDto.setAddress(normalizedAddress);
171	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
172	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
173	            .filter(existing -> lastName.equals(normalizeHousehold(existing.getLastName()))
174	                && normalizedAddress.equals(normalizeAddress(existing.getAddress())))
175	            .toList();
176	        String householdId = null;
177	        if (!householdMembers.isEmpty()) {
178	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
179	                throw new DuplicateHouseholdException(
180	                    "an owner with the same last name and address already exists");
181	            }
182	            // Joining an existing household: share a stable identifier with every member,
183	            // backfilling any members created before the household was formed.
184	            householdId = householdId(lastName, normalizedAddress);
185	            for (Owner member : householdMembers) {
186	                if (!householdId.equals(member.getHouseholdId())) {
187	                    member.setHouseholdId(householdId);
188	                    this.clinicService.saveOwner(member);
189	                }
190	            }
191	        }
192	        String telephone = toE164(ownerFieldsDto.getTelephone());
193	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
194	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
195	        if (telephoneInUse) {
196	            throw new DuplicateTelephoneException(
197	                "an owner with the same E.164 telephone already exists");
198	        }
199	        ownerFieldsDto.setTelephone(telephone);
200	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
201	        HttpHeaders headers = new HttpHeaders();
202	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
203	        owner.setRegistrationDate(registrationDate);
204	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
205	        owner.setHouseholdId(householdId);
206	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
207	        owner.setBulkSignupWarning(bulkSignupWarning);
208	        // Household size after this create: existing members plus the owner being created.
209	        owner.setHouseholdSize(householdMembers.size() + 1);
210	        this.clinicService.saveOwner(owner);
211	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
212	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
213	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
214	            ownerDto.getMembershipLevel());
215	        headers.setLocation(UriComponentsBuilder.newInstance()
216	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
217	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
218	    }
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
223	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
224	        if (currentOwner == null) {
225	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
226	        }
227	        currentOwner.setAddress(ownerFieldsDto.getAddress());
228	        currentOwner.setCity(ownerFieldsDto.getCity());
229	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
230	        currentOwner.setLastName(ownerFieldsDto.getLastName());
231	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
232	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
233	        this.clinicService.saveOwner(currentOwner);
234	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
235	    }
236	
237	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
238	    @Transactional
239	    @Override
240	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
241	        Owner owner = this.clinicService.findOwnerById(ownerId);
242	        if (owner == null) {
243	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
244	        }
245	        this.clinicService.deleteOwner(owner);
246	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
247	    }
248	
249	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
250	    @Override
251	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
252	        Owner owner = this.clinicService.findOwnerById(ownerId);
253	        if (owner == null) {
254	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
255	        }
256	        HttpHeaders headers = new HttpHeaders();
257	        Pet pet = petMapper.toPet(petFieldsDto);
258	        owner.setId(ownerId);
259	        pet.setOwner(owner);
260	        pet.getType().setName(null);
261	        this.clinicService.savePet(pet);
262	        PetDto petDto = petMapper.toPetDto(pet);
263	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
264	            .buildAndExpand(pet.getId()).toUri());
265	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
266	    }
267	
268	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
269	    @Override
270	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
271	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
272	        if (currentOwner != null) {
273	            Pet currentPet = this.clinicService.findPetById(petId);
274	            if (currentPet != null) {
275	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
276	                currentPet.setName(petFieldsDto.getName());
277	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
278	                this.clinicService.savePet(currentPet);
279	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
280	            }
281	        }
282	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
283	    }
284	
285	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
286	    @Override
287	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
288	        HttpHeaders headers = new HttpHeaders();
289	        Visit visit = visitMapper.toVisit(visitFieldsDto);
290	        Pet pet = new Pet();
291	        pet.setId(petId);
292	        visit.setPet(pet);
293	        this.clinicService.saveVisit(visit);
294	        VisitDto visitDto = visitMapper.toVisitDto(visit);
295	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
296	            .buildAndExpand(visit.getId()).toUri());
297	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
298	    }
299	
300	
301	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
302	    @Override
303	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
304	        Owner owner = this.clinicService.findOwnerById(ownerId);
305	        if (owner != null) {
306	            Pet pet = owner.getPet(petId);
307	            if (pet != null) {
308	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
309	            }
310	        }
311	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
312	    }
313	
314	    private static boolean isBlank(String value) {
315	        return value == null || value.isBlank();
316	    }
317	
318	    /**
319	     * Rolls a registration date forward to the next business day: when it falls on a Saturday or
320	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
321	     * to the effective registration date (whether supplied in the request or defaulted to the server
322	     * date), so every value derived from the registration date sees the adjusted business day.
323	     */
324	    private static LocalDate toBusinessDay(LocalDate date) {
325	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
326	            date = date.plusDays(1);
327	        }
328	        return date;
329	    }
330	
331	    /**
332	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
333	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
334	     * lower-cased so that last names are compared case-insensitively.
335	     */
336	    private static String normalizeHousehold(String value) {
337	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
338	    }
339	
340	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
341	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
342	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
343	
344	    /**
345	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
346	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
347	     * upper-cased, and common street-type abbreviations are expanded token-by-token
348	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
349	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
350	     * used for every address comparison (household-duplicate detection and the shared household id).
351	     */
352	    private static String normalizeAddress(String value) {
353	        if (value == null) {
354	            return "";
355	        }
356	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
357	        if (collapsed.isEmpty()) {
358	            return "";
359	        }
360	        String[] tokens = collapsed.split(" ");
361	        StringBuilder sb = new StringBuilder();
362	        for (int i = 0; i < tokens.length; i++) {
363	            if (i > 0) {
364	                sb.append(' ');
365	            }
366	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
367	        }
368	        return sb.toString();
369	    }
370	
371	    /**
372	     * Derives the stable {@code householdId} shared by all owners in a household. It is a
373	     * deterministic function of the normalized last name and address, so every owner that
374	     * shares those values maps to the same identifier regardless of creation order.
375	     */
376	    private static String householdId(String normalizedLastName, String normalizedAddress) {
377	        String key = normalizedLastName + "\n" + normalizedAddress;
378	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
379	    }
380	
381	    /**
382	     * Builds the {@code customerCode} assigned to a new owner, formatted
383	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
384	     * owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last name,
385	     * and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the number
386	     * of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
387	     */
388	    private String nextCustomerCode(String city, String lastName) {
389	        String city3 = prefix3(city);
390	        String last3 = prefix3(lastName);
391	        long sequence = this.clinicService.findAllOwners().stream()
392	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
393	            .count() + 1L;
394	        return String.format("%s-%s-%04d", city3, last3, sequence);
395	    }
396	
397	    /** Upper-cased first three letters (any non-letter removed) of the given value. */
398	    private static String prefix3(String value) {
399	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
400	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
401	    }
402	
403	    /**
404	     * Counts the existing owners that share the given first name and last name, compared
405	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
406	     * owner currently being created is saved), so it reflects how many namesakes preceded the
407	     * new owner.
408	     */
409	    private int countNamesakes(String firstName, String lastName) {
410	        return (int) this.clinicService.findAllOwners().stream()
411	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
412	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
413	            .count();
414	    }
415	
416	    /**
417	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
418	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
419	     * national one, a single leading {@code '0'} is dropped, and the default country code
420	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'},
421	     * otherwise an {@link InvalidTelephoneException} is raised (reported to the client as 400).
422	     */
423	    private static String toE164(String telephone) {
424	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
425	        String digits;
426	        if (cleaned.startsWith("+")) {
427	            digits = cleaned.substring(1);
428	        } else {
429	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
430	            digits = "61" + national;
431	        }
432	        if (!digits.matches("[0-9]{8,15}")) {
433	            throw new InvalidTelephoneException(
434	                "telephone must form a valid E.164 number with 8 to 15 digits");
435	        }
436	        return "+" + digits;
437	    }
438	
439	    /**
440	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
441	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
442	     * is raised (reported to the client as 400). A valid value is returned lower-cased so it is
443	     * stored and returned in canonical form.
444	     */
445	    private static String normalizeEmail(String email) {
446	        if (isBlank(email)) {
447	            return null;
448	        }
449	        String trimmed = email.trim();
450	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
451	            throw new InvalidEmailException("email must be a syntactically valid address");
452	        }
453	        return trimmed.toLowerCase(Locale.ROOT);
454	    }
455	}
